goog.provide('Blockly.Loongson.pins');

goog.require('Blockly.Loongson');
/*---------------------------------------------------------------------------------------*/
//PIN
/* 
# generated by OpenBlock
from loongpio import *
from loongpio.pins import *

duty = 0

_GPIO1 = DigitalOutput(GPIO1)

_GPIO1.value = 1
*/
Blockly.Loongson['loongson_pin_setDigitalOutput'] = function (block) {
  Blockly.Loongson.imports_["loongpio"] = "from loongpio import *";
  Blockly.Loongson.imports_["loongpio.pins"] = "from loongpio.pins import *";

  var pin = block.getFieldValue('PIN') || 'GPIO1';
  var level = Blockly.Loongson.valueToCode(block, 'LEVEL', Blockly.Loongson.ORDER_FUNCTION_CALL) || 'LOW';

  Blockly.Loongson.setups_[`_${pin}`] = `_${pin} = DigitalOutput(${pin})`
  var code = `_${pin}.value = ${level}\n`;

  return code;
};

Blockly.Loongson['loongson_pin_menu_level'] = function (block) {
  var code = block.getFieldValue('level') || '0';
  return [code, Blockly.Loongson.ORDER_ATOMIC];
};

/* 
# generated by OpenBlock
from loongpio import *
from loongpio.pins import *

duty = 0

_PWM0 = PWMOutput(PWM0)

_PWM0.duty_cycle = (50 * 655.35)

*/
Blockly.Loongson['loongson_pin_setPwmOutput'] = function (block) {
  Blockly.Loongson.imports_["loongpio"] = "from loongpio import *";
  Blockly.Loongson.imports_["loongpio.pins"] = "from loongpio.pins import *";

  var pin = block.getFieldValue('PIN') || 'GPIO1';
  var out = Blockly.Loongson.valueToCode(block, 'OUT', Blockly.Loongson.ORDER_FUNCTION_CALL) || '50';
  Blockly.Loongson.setups_[`_${pin}`] = `_${pin} = PWMOutput(${pin})`

  var code = `_${pin}.duty_cycle = int(${out} * 65535 / 100)\n`;

  return code;
};


/* 
# generated by OpenBlock
from loongpio import *
from loongpio.pins import *
_GPIO1 = DigitalOutput(GPIO1)
_GPIO1.value = (not _GPIO1.value)
*/
Blockly.Loongson['loongson_pin_readDigitalPin'] = function (block) {
  Blockly.Loongson.imports_["loongpio"] = "from loongpio import *";
  Blockly.Loongson.imports_["loongpio.pins"] = "from loongpio.pins import *";

  var pin = block.getFieldValue('PIN') || 'GPIO1';
  Blockly.Loongson.setups_[`_${pin}`] = `_${pin} = DigitalOutput(${pin})`

  var code = `_${pin}.value`;
  return [code, Blockly.Loongson.ORDER_ATOMIC];
};


Blockly.Loongson['loongson_pin_waitButtonPressed'] = function (block) {
  Blockly.Loongson.imports_["loongpio"] = "from loongpio import *";
  Blockly.Loongson.imports_["loongpio.pins"] = "from loongpio.pins import *";

  var pin = block.getFieldValue('PIN') || 'GPIO5';
  var level = Blockly.Loongson.valueToCode(block, 'LEVEL',
    Blockly.Loongson.ORDER_FUNCTION_CALL) || 'LOW';

  Blockly.Loongson.setups_[`_${pin}`] =
    `_${pin} = Button(${pin}, is_active_low=bool(1 - ${level}))`

  var code = `_${pin}.wait_until_press()\n`
  return code;
};


Blockly.Loongson['loongson_pin_buttonPressed'] = function (block) {
  Blockly.Loongson.imports_["loongpio"] = "from loongpio import *";
  Blockly.Loongson.imports_["loongpio.pins"] = "from loongpio.pins import *";

  var pin = block.getFieldValue('PIN') || 'GPIO5';
  var level = Blockly.Loongson.valueToCode(block, 'LEVEL',
    Blockly.Loongson.ORDER_FUNCTION_CALL) || 'LOW';

  Blockly.Loongson.setups_[`_${pin}`] =
    `_${pin} = Button(${pin}, is_active_low=bool(1 - ${level}))`

  var code = `_${pin}.is_pressed`
  return [code, Blockly.Loongson.ORDER_ATOMIC];
};


//set direction of Motor L298N
Blockly.Loongson['loongson_pin_motor'] = function (block) {
  Blockly.Loongson.imports_["loongpio"] = "from loongpio import *";
  Blockly.Loongson.imports_["loongpio.pins"] = "from loongpio.pins import *";
  var pin1 = block.getFieldValue('PIN1') || 'GPIO5';
  var pin2 = block.getFieldValue('PIN2') || 'GPIO6';
  var direction = block.getFieldValue('DIRECTION') || '1';
  Blockly.Loongson.setups_[`_${pin1}`] = `_${pin1} = DigitalOutput(${pin1})`
  Blockly.Loongson.setups_[`_${pin2}`] = `_${pin2} = DigitalOutput(${pin2})`
  var code = ``;
  if (direction == '-1') {
      code = `_${pin1}.value = ${0}\n` +
          `_${pin2}.value = ${0}\n`;
  }
  else {
      code = `_${pin1}.value = ${direction}\n` +
          `_${pin2}.value = (1-${direction})\n`;
  }
  return code;
};
/*---------------------------------------------------------------------------------------*/